import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.Dsf4_p3t.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/faq.md","filePath":"zh/guide/faq.md","lastUpdated":1787565985000}'),d={name:"zh/guide/faq.md"};function l(s,e,r,h,n,c){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to &quot;基础&quot;">​</a></h2><h3 id="neoflux-是什么" tabindex="-1">NeoFlux 是什么？ <a class="header-anchor" href="#neoflux-是什么" aria-label="Permalink to &quot;NeoFlux 是什么？&quot;">​</a></h3><p>NeoFlux 是一个轻量级跨平台 C++20 UI 框架，采用两层架构：Application 层运行业务逻辑和 Taitank flex 布局引擎，Render 层通过 tgfx（移动端）或 GLFW（桌面端）消费渲染命令。</p><h3 id="为什么用-c-20" tabindex="-1">为什么用 C++20？ <a class="header-anchor" href="#为什么用-c-20" aria-label="Permalink to &quot;为什么用 C++20？&quot;">​</a></h3><p>C++20 支持协程（<code>co_await</code>）、concepts、<code>std::span</code>、designated initializers 和 <code>std::bit_ceil</code>。框架全程使用这些特性实现简洁高效的代码。</p><h3 id="neoflux-可以用于生产环境吗" tabindex="-1">NeoFlux 可以用于生产环境吗？ <a class="header-anchor" href="#neoflux-可以用于生产环境吗" aria-label="Permalink to &quot;NeoFlux 可以用于生产环境吗？&quot;">​</a></h3><p>NeoFlux 正在积极开发中。核心架构（widget 树、flex 布局、渲染管线、输入分发）已可用。当前限制请查看 GitHub issues。</p><h2 id="构建" tabindex="-1">构建 <a class="header-anchor" href="#构建" aria-label="Permalink to &quot;构建&quot;">​</a></h2><h3 id="如何构建-neoflux" tabindex="-1">如何构建 NeoFlux？ <a class="header-anchor" href="#如何构建-neoflux" aria-label="Permalink to &quot;如何构建 NeoFlux？&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j</span></span></code></pre></div><p>示例和测试默认关闭。启用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_BUILD_EXAMPLES=ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_BUILD_TESTS=ON</span></span></code></pre></div><h3 id="为什么第一次构建很慢" tabindex="-1">为什么第一次构建很慢？ <a class="header-anchor" href="#为什么第一次构建很慢" aria-label="Permalink to &quot;为什么第一次构建很慢？&quot;">​</a></h3><p>NeoFlux 使用 FetchContent 下载并构建第三方依赖（glog、gflags、glfw、taitank、freetype、gtest）。后续构建很快，因为依赖缓存在 <code>thirdparty/_deps/</code> 中。</p><h3 id="如何交叉编译" tabindex="-1">如何交叉编译？ <a class="header-anchor" href="#如何交叉编译" aria-label="Permalink to &quot;如何交叉编译？&quot;">​</a></h3><p>为目标平台设置 CMake toolchain 文件。NeoFlux 使用平台宏（<code>NEOFLUX_PLATFORM_DESKTOP</code>、<code>NEOFLUX_PLATFORM_MOBILE</code>、<code>NEOFLUX_PLATFORM_WINDOWS</code> 等）选择合适的后端。</p><h2 id="渲染" tabindex="-1">渲染 <a class="header-anchor" href="#渲染" aria-label="Permalink to &quot;渲染&quot;">​</a></h2><h3 id="支持哪些渲染后端" tabindex="-1">支持哪些渲染后端？ <a class="header-anchor" href="#支持哪些渲染后端" aria-label="Permalink to &quot;支持哪些渲染后端？&quot;">​</a></h3><ul><li><strong>Vulkan</strong>（默认）— 通过 tgfx</li><li><strong>OpenGL</strong> — 通过 tgfx/GLFW</li><li><strong>CPU</strong> — 软件渲染（回退）</li></ul><p>使用 <code>--render_backend=vulkan|gl|cpu</code> 选择。</p><h3 id="为什么窗口是黑的" tabindex="-1">为什么窗口是黑的？ <a class="header-anchor" href="#为什么窗口是黑的" aria-label="Permalink to &quot;为什么窗口是黑的？&quot;">​</a></h3><p>常见原因：</p><ol><li><strong>未加载字体</strong> — Text widget 需要字体目录中有 <code>.ttf</code>/<code>.otf</code> 文件。在 <code>Init()</code> 前调用 <code>app.SetFontDir(&quot;fonts&quot;)</code>。</li><li><strong>未 push route</strong> — 所有示例需要 <code>RouteRegistry::RegisterRoute()</code> 然后 <code>app.PushRoute(&quot;/&quot;)</code>。</li><li><strong>窗口未暴露</strong> — 某些平台上第一帧可能需要 resize 或 focus 事件。</li></ol><h3 id="为什么文字乱码" tabindex="-1">为什么文字乱码？ <a class="header-anchor" href="#为什么文字乱码" aria-label="Permalink to &quot;为什么文字乱码？&quot;">​</a></h3><p>字体文件不包含你尝试渲染的字形。使用支持你字符集的字体（例如 CJK 用 NotoSansSC）。</p><h2 id="widget" tabindex="-1">Widget <a class="header-anchor" href="#widget" aria-label="Permalink to &quot;Widget&quot;">​</a></h2><h3 id="如何创建自定义-widget" tabindex="-1">如何创建自定义 Widget？ <a class="header-anchor" href="#如何创建自定义-widget" aria-label="Permalink to &quot;如何创建自定义 Widget？&quot;">​</a></h3><p>继承 <code>Widget</code>（或 <code>StatelessWidget</code>/<code>StatefulWidget</code>）并重写相关虚函数：<code>Build()</code>、<code>OnMeasure()</code>、<code>Paint()</code> 和事件处理函数。参见 <a href="./widgets">Widget 系统</a>。</p><h3 id="markneedsbuild-和-markframedirty-有什么区别" tabindex="-1"><code>MarkNeedsBuild()</code> 和 <code>MarkFrameDirty()</code> 有什么区别？ <a class="header-anchor" href="#markneedsbuild-和-markframedirty-有什么区别" aria-label="Permalink to &quot;`MarkNeedsBuild()` 和 `MarkFrameDirty()` 有什么区别？&quot;">​</a></h3><ul><li><code>MarkNeedsBuild()</code> — 标记 widget 在下一帧重建（子组件可能变化）。</li><li><code>MarkFrameDirty()</code> — 触发 layout/paint 循环而不重建 widget。用于绘制时变化（例如拖拽偏移、滚动位置）。</li></ul><h3 id="为什么我的-draggable-不跟随光标" tabindex="-1">为什么我的 Draggable 不跟随光标？ <a class="header-anchor" href="#为什么我的-draggable-不跟随光标" aria-label="Permalink to &quot;为什么我的 Draggable 不跟随光标？&quot;">​</a></h3><p>确保没有在 <code>OnPointerMove()</code> 中调用 <code>MarkNeedsBuild()</code> —— 拖拽偏移仅在绘制时应用。框架在指针事件时自动调用 <code>MarkFrameDirty()</code>。</p><h2 id="布局" tabindex="-1">布局 <a class="header-anchor" href="#布局" aria-label="Permalink to &quot;布局&quot;">​</a></h2><h3 id="为什么我的-widget-不可见" tabindex="-1">为什么我的 Widget 不可见？ <a class="header-anchor" href="#为什么我的-widget-不可见" aria-label="Permalink to &quot;为什么我的 Widget 不可见？&quot;">​</a></h3><ul><li>Widget 尺寸为零（检查 <code>OnMeasure()</code> 返回值）。</li><li>Widget 在视口外（检查 flex 约束）。</li><li>Widget 被 <code>ScrollView</code> 或 <code>ClipRect</code> 裁剪。</li></ul><h3 id="如何让-widget-填充可用空间" tabindex="-1">如何让 Widget 填充可用空间？ <a class="header-anchor" href="#如何让-widget-填充可用空间" aria-label="Permalink to &quot;如何让 Widget 填充可用空间？&quot;">​</a></h3><p>使用 <code>Expanded</code>（设置 <code>flex_grow</code>）或在 flex 容器中设置 <code>SetWidth(0)</code> 配合 <code>flex_grow &gt; 0</code>。</p><h2 id="线程" tabindex="-1">线程 <a class="header-anchor" href="#线程" aria-label="Permalink to &quot;线程&quot;">​</a></h2><h3 id="neoflux-线程安全吗" tabindex="-1">NeoFlux 线程安全吗？ <a class="header-anchor" href="#neoflux-线程安全吗" aria-label="Permalink to &quot;NeoFlux 线程安全吗？&quot;">​</a></h3><p>Widget 树仅从主线程访问。渲染层在独立线程运行，通过 SPSC 环形队列通信。不要从渲染线程访问 widget。</p><h3 id="协程如何工作" tabindex="-1">协程如何工作？ <a class="header-anchor" href="#协程如何工作" aria-label="Permalink to &quot;协程如何工作？&quot;">​</a></h3><p>NeoFlux 提供 <code>Task&lt;T&gt;</code> 协程类型，支持 <code>co_await Yield()</code>（下一帧）和 <code>co_await Sleep(duration)</code>。协程由 <code>EventLoop</code> 在主线程调度。使用 <code>std::weak_ptr</code> 防止 <code>co_await</code> 期间 widget 销毁。</p><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><h3 id="应用启动时崩溃" tabindex="-1">应用启动时崩溃 <a class="header-anchor" href="#应用启动时崩溃" aria-label="Permalink to &quot;应用启动时崩溃&quot;">​</a></h3><p>检查：</p><ol><li>字体目录存在且包含有效字体文件。</li><li><code>Init()</code> 在 <code>Run()</code> 之前调用。</li><li>已注册并 push route。</li><li>渲染后端在你的平台上受支持。</li></ol><h3 id="clang-tidy-报告警告" tabindex="-1">clang-tidy 报告警告 <a class="header-anchor" href="#clang-tidy-报告警告" aria-label="Permalink to &quot;clang-tidy 报告警告&quot;">​</a></h3><p>运行 <code>clang-tidy -p build src/**/*.cpp</code> 检查。项目目标是零警告。完整检查清单见 <a href="./contributing">贡献指南</a>。</p><h3 id="如何启用详细日志" tabindex="-1">如何启用详细日志？ <a class="header-anchor" href="#如何启用详细日志" aria-label="Permalink to &quot;如何启用详细日志？&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./my_app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose_logging=true</span></span></code></pre></div><p>日志默认写入 <code>logs/</code>。使用 <code>--logtostderr=true</code> 输出到 stderr。</p>',52)])])}const g=a(d,[["render",l]]);export{u as __pageData,g as default};
